from typing import Union, Dict

from taf.gnb.oam.coam.vdu.exceptions import WrongApiResponseStatus, TimeoutException
from taf.internal.gnb.oam.coam.vdu.client.cp_config_licensed.v1.exceptions import ApiException

from taf.rfrl.procedures.resources.python.bts.components.cell.cloud_cell import CloudCell
from taf.rfrl.procedures.resources.python.bts.components.rmod.cloud_rmod import CloudRmod
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import Api
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info, log_debug
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import RfDiagnosticTestUnexpectedResult


class RfDiagnosticTest:
    """ Handles RF Diagnostic Test functionality on BTS. """

    def __init__(self, api: Api, api_alias: str):
        """
        :param api: API used for handling RF Diagnostic Test on BTS
        :param api_alias: name of opened API connection which this RF Diagnostic Test should use
        """
        self._api = api
        self._api_alias = api_alias

    @pretty_log
    def run_rf_diagnostic_test(self, cell: Union[CloudCell, None], timeout: int = 120):
        """
        Starts RF Diagnostic Test for given cell or all cells from NR RAT.
        :param cell: cell for which RF Diagnostic Test should be run;
                     if None provided then RF Diagnostic Test will be run for all cells from NR RAT.
        :param timeout: time (in seconds) in which RF Diagnostic Test should be successfully completed; defaults to 120
        :raises RfDiagnosticTestUnexpectedResult: if starting RF Diagnostic Test fails
        """
        rat_msg = 'all cells from NR RAT'
        log_info(f'Running RF Diagnostic Test for {cell.name if cell else rat_msg}', to_console=True)
        result_msg = 'Result of starting RF Diagnostic Test is: {}'

        try:
            all_nr_cells = -1
            self._api.start_rf_diagnostic_test(nr_cell_id=int(cell.id) if cell else all_nr_cells,
                                               timeout=timeout,
                                               vdu_connection=self._api_alias)
        except (ApiException,
                WrongApiResponseStatus,
                TimeoutException) as api_error:
            raise RfDiagnosticTestUnexpectedResult(result_msg.format(api_error))

        log_debug(result_msg.format('success'))

    @pretty_log
    def run_rf_statistics_diagnostic_test(self, rmod: Union[CloudRmod, None], timeout: int = 240):
        """
        Starts RF Statistics Diagnostic Test for given RMOD or all RMODs.
        :param rmod: RMOD for which RF Statistics Diagnostic Test should be run;
                     if None provided then RF Statistics Diagnostic Test will be run for all RMODs.
        :param timeout: time (in seconds) in which RF Statistics Diagnostic Test should be successfully completed;
                        defaults to 240
        :raises RfDiagnosticTestUnexpectedResult: if starting RF Statistics Diagnostic Test fails
        """
        all_rmods_msg = 'all rmods'
        log_info(f'Running RF Statistics Diagnostic Test for {rmod.name if rmod else all_rmods_msg}', to_console=True)
        result_msg = 'Result of starting RF Statistics Diagnostic Test is: {}'

        try:
            all_rmods = -1
            self._api.start_diagnostic_rf_statistics_diagnostic_test(
                target_rmod_id=int(rmod.id) if rmod else all_rmods,
                timeout=timeout,
                vdu_connection=self._api_alias)
        except (ApiException,
                WrongApiResponseStatus,
                TimeoutException) as api_error:
            raise RfDiagnosticTestUnexpectedResult(result_msg.format(api_error))

        log_debug(result_msg.format('success'))

    @pretty_log
    def get_rf_diagnostic_test_results(self, timeout: int = 120) -> Dict:
        """
        Returns all available results of RF Diagnostic Test.
        :param timeout: time (in seconds) in which RF Diagnostic Test results should be successfully retrieved; defaults to 120
        :return: results of RF Diagnostic Test, i.e.
                 {'bts_id': '8482',
                  'bts_name': 'vDU_8482_PZ1_TDD_1',
                  'rf_diagnostic_test_results': [{'cell_name': None,
                                                  'dist_name': 'MRBTS-8482/MNL-1/MNLENT-1/TEST-1/RFREQ-0/RFRES-1',
                                                  'general_test_info': {'actual_start_time': '2024-10-04T07:08:08+00:00',
                                                                        'actual_stop_time': '2024-10-04T07:08:10+00:00',
                                                                        'detailed_result': [{'antl_id': 1,
                                                                                             'phyant_id': None,
                                                                                             'product_name': 'AZQL',
                                                                                             'rmod_id': 1,
                                                                                             'rssi_dbm': -140.0,
                                                                                             'sinr_db': -20,
                                                                                             'vswr': 0.0}],
                                                                        'fwd_et_pd_bm': 27.7,
                                                                        'fwd_etpw': 0.6,
                                                                        'fwd_test_disp': 'pass',
                                                                        'result': 'success',
                                                                        'rvrs_test_disp': 'pass',
                                                                        'test_outcome': 'pass',
                                                                        'test_outcome_additional_info': '-'},
                                                                        'nr_cell_id': 1}]}
        :raises RfDiagnosticTestUnexpectedResult: if getting RF Diagnostic Test results fails
        """
        log_info('Getting RF Diagnostic Test results', to_console=True)
        result_msg = 'RF Diagnostic Test results are: {}'

        try:
            test_results = self._api.get_diagnostic_rf_diagnostic_test_results(timeout=timeout,
                                                                               vdu_connection=self._api_alias)
        except (ApiException,
                WrongApiResponseStatus,
                TimeoutException) as api_error:
            raise RfDiagnosticTestUnexpectedResult(result_msg.format(api_error))

        log_debug(result_msg.format(test_results))
        return test_results

