    @pretty_log
    def clear_rf_diagnostic_test_results(self, timeout: int = 120):
        """
        Clears RF Diagnostic Test results.
        :param timeout: time (in seconds) in which RF Diagnostic Test results should be successfully cleared; defaults to 120
        :raises RfDiagnosticTestUnexpectedResult: if clearing RF Diagnostic Test results fails
        """
        log_info('Clearing RF Diagnostic Test results', to_console=True)
        result_msg = 'Result of clearing RF Diagnostic Test results is: {}'

        try:
            self._api.clear_rf_diagnostic_test_results(timeout=timeout,
                                                       vdu_connection=self._api_alias)
        except (ApiException,
                WrongApiResponseStatus,
                TimeoutException) as api_error:
            raise RfDiagnosticTestUnexpectedResult(result_msg.format(api_error))

        log_debug(result_msg.format('success'))

    @pretty_log
    def clear_rf_statistics_diagnostic_test_results(self, timeout: int = 120):
        """
        Clears RF Statistics Diagnostic Test results.
        :param timeout: time (in seconds) in which RF Statistics Diagnostic Test results should be successfully cleared; defaults to 120
        :raises RfDiagnosticTestUnexpectedResult: if clearing RF Statistics Diagnostic Test results fails
        """
        log_info('Clearing RF Statistics Diagnostic Test results', to_console=True)
        result_msg = 'Result of clearing RF Statistics Diagnostic Test results is: {}'

        try:
            self._api.clear_rf_statistics_diagnostic_test_results(timeout=timeout,
                                                                  vdu_connection=self._api_alias)
        except (ApiException,
                WrongApiResponseStatus,
                TimeoutException) as api_error:
            raise RfDiagnosticTestUnexpectedResult(result_msg.format(api_error))

        log_debug(result_msg.format('success'))
